@spec editor_verbs_spec  src=tests/specs/editor_verbs_spec.lua  loc=165  sha=3eaf95c  cases=7
@exercises swingEditor (se), configManager (h.cm)
@surface   se:open, se:libraryDescriptor, cm:getAt
@harness   mk

# Intent
  Verb descriptors on the swing/temper editors under the library model:
  `publish` lifts a project copy into the shared library, `revert` discards
  project drift back to its source, and `tidy` (swing only) drops pristine
  unreferenced project copies. Instantiated over a harness cm/ds with a lib
  service; imgui stubbed via package.preload. Recipe lifted from
  temperEditor_tree_spec.

# Helpers
  @fn mkLib(h)  @ 19-24
  @fn facadeStub()  @ 28-37
      -- Swing reaches the arrange/tracker services only for the reference scan and
      -- default-slot resolution; a leaf on each covers the descriptor path.
  @fn mkSwing(h)  @ 39-49
  @fn mkTemper(h, inUse)  @ 51-61

# Cases
  @case 'swing onPublish lifts a project copy into the library tier'  [harness]  @ 65-76
  @case 'swing onRevert restores a divergent project copy from its source'  [harness]  @ 79-92
  @case 'swing descriptor flags a divergent project row as modified'  [harness]  @ 95-106
  @case 'temper descriptor flags a divergent project row as modified'  [harness]  @ 109-120
  @case 'swing and temper descriptors both expose onTidy'  [harness]  @ 123-131
  @case 'swing onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 134-147
  @case 'temper onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 150-163

# Uses (outbound edges)
  @use call se:open  @ 47
  @use call se:libraryDescriptor  @ 72,89,129,142
  @use call cm:getAt  @ 74,144,145,160,161

